const abandonados = $input.all().map(i => i.json);
const webhookData = $('Webhook — Interés detectado').first().json.body || {};

// Group by customer, collect their abandoned products
const byCustomer = {};
for (const row of abandonados) {
  if (!byCustomer[row.email]) {
    byCustomer[row.email] = { id: row.id, nombre: row.nombre, email: row.email, localidad: row.localidad, productos: [] };
  }
  byCustomer[row.email].productos.push({ sku: row.sku, nombre: row.product_nombre, precio: row.precio_unitario });
}

return Object.values(byCustomer).map(customer => ({
  json: {
    customer_id: customer.id,
    customer_nombre: customer.nombre,
    customer_email: customer.email,
    customer_localidad: customer.localidad,
    productos_abandonados: customer.productos,
    total_items: customer.productos.length,
    descuento_sugerido: customer.productos.length >= 3 ? '10%' : null
  }
}));

const d = $input.first().json;
const productos_html = d.productos_abandonados.map(p => `<li><strong>${p.nombre}</strong> — $${p.precio.toLocaleString('es-AR')}</li>`).join('');
return [{ json: {
  to: d.customer_email,
  subject: `${d.customer_nombre}, ¡tenemos una oferta especial para vos!`,
  html: `<h2>Hola ${d.customer_nombre}!</h2>
<p>Notamos que dejaste algunos productos sin confirmar. Por eso, te ofrecemos un <strong>${d.descuento_sugerido} de descuento</strong> en tu próximo pedido.</p>
<ul>${productos_html}</ul>
<p>Contactanos para concretar tu pedido con el descuento aplicado.</p>
<p><em>Golden Harvest S.A. — ${d.customer_localidad}</em></p>`,
  tipo: 'oferta_prioritaria', simulated: true
} }];

